import { defineConfig } from "vite";

export default defineConfig({
  server: { port: 9355, strictPort: true },
  preview: { port: 9355, strictPort: true },
});

export type Action =
  | "seek-fruit"
  | "eat"
  | "wander"
  | "avoid-crowd"
  | "flee"
  | "hunt"
  | "pause"
  | "digest";

