  const st = Math.sin(cam.tilt);
  const ct = Math.cos(cam.tilt);
  return {
    cx,
    cy,
    px,
    project(x: number, y: number, z: number): Proj {
      const xr = x * c - z * s;
      const zr = x * s + z * c;
      const persp = 1 / (1 + (radius - zr) * 0.012);
      const k = px * persp;
      return {
