:root {
  color: #2a241c;
  background: #c48955;
  font-family: "Avenir Next", "Trebuchet MS", "Segoe UI", sans-serif;
  line-height: 1.4;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1100px 640px at 50% 0%, #e2b57e, transparent 70%),
    #c48955;
}

button, input { font: inherit; color: inherit; }

.app {
  width: min(1180px, calc(100% - 24px));
  margin: 0 auto;
  padding: 16px 0 28px;
}

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 18px;
  margin-bottom: 12px;
}

h1 {
  margin: 0;
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  letter-spacing: -0.03em;
  line-height: 1;
}

h2 {
  margin: 0 0 4px;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
}

.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

button {
  background: #fff8ec;
  border: 1px solid #ddc7a4;
  border-radius: 999px;
  padding: 0.42rem 0.85rem;
  box-shadow: 0 3px 0 #b88958;
  cursor: pointer;
}

button:disabled {
  opacity: 0.45;
  cursor: default;
}

button[aria-pressed="true"], button.primary {
  background: #2f6a45;
  color: #f4fff6;
  border-color: #245538;
}

button:focus-visible, input:focus-visible {
  outline: 2px solid #2a241c;
  outline-offset: 2px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #fff8ec;
  border-radius: 999px;
  padding: 0.25rem 0.7rem;
  border: 1px solid #ddc7a4;
}

.speed input { width: 110px; }

.clock {
  min-width: 7.2rem;
  font-variant-numeric: tabular-nums;
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 380px);
  gap: 14px;
}

.stage-card, .panel, .card {
  background: #fff8ec;
  border: 1px solid #e4d2b6;
  border-radius: 16px;
  box-shadow: 0 8px 0 rgba(120, 72, 32, 0.18);
}

.stage-card { position: relative; padding: 10px; }

.stage-frame {
  height: min(70vh, 720px);
  min-height: 420px;
  border-radius: 12px;
  overflow: hidden;
  background: #e7c99a;
}

#garden {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

#garden.dragging { cursor: grabbing; }

.stage-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  padding: 8px 6px 2px;
}

.hint, .note {
  margin: 0;
  color: #5c5146;
  font-size: 0.92rem;
}

.beads {
  display: flex;
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-variant-numeric: tabular-nums;
}

.beads i {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 99px;
  margin-right: 0.3rem;
}

.fruit { background: #67a832; }
.blue { background: #2a74d6; }
.red { background: #d24b43; }

#inspect {
  position: absolute;
  left: 18px;
  bottom: 52px;
  width: min(280px, calc(100% - 36px));
  background: #fff8ec;
  border: 1px solid #e4d2b6;
  border-radius: 14px;
  padding: 10px 12px;
  box-shadow: 0 6px 0 rgba(120, 72, 32, 0.16);
}

#inspect h2 { font-size: 1rem; }

#inspect dl {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 10px;
  margin: 8px 0 0;
}

#inspect dt { color: #5c5146; }
#inspect dd { margin: 0; font-variant-numeric: tabular-nums; }

.panel {
  padding: 12px 12px 4px;
  max-height: calc(70vh + 48px);
  overflow: auto;
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 8px;
}

.presets button {
  padding: 0.35rem 0.65rem;
  font-size: 0.86rem;
}

.blurb {
  min-height: 2.6em;
  margin: 0 0 10px;
  color: #5c5146;
}

fieldset {
  border: 0;
  padding: 0;
  margin: 0 0 12px;
}

legend {
  font-weight: 600;
  margin-bottom: 6px;
}

.setup-note {
  margin: 0 0 8px;
  color: #5c5146;
  font-size: 0.86rem;
}

.field {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0 8px;
  margin-bottom: 8px;
}

.field label { font-size: 0.9rem; }

.field .value {
  font-variant-numeric: tabular-nums;
  color: #5c5146;
}

.field input[type="range"] { grid-column: 1 / -1; width: 100%; }

.field input[type="number"] {
  grid-column: 1 / -1;
  width: 100%;
  border: 1px solid #e4d2b6;
  border-radius: 8px;
  padding: 0.3rem 0.45rem;
  background: #fff;
}

.group-garden { accent-color: #2f6a45; }
.group-blue { accent-color: #2a74d6; }
.group-red { accent-color: #d24b43; }
.group-setup { accent-color: #8a5a32; }

.charts {
  margin-top: 14px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.card { padding: 12px 14px 14px; }

.card canvas {
  width: 100%;
  height: 220px;
  display: block;
  margin-top: 8px;
}

.span { grid-column: 1 / -1; }

.legend { margin: 8px 0 0; font-variant-numeric: tabular-nums; }

#summary p { margin: 0 0 6px; }

@media (max-width: 900px) {
  .layout, .charts { grid-template-columns: 1fr; }
  .panel { max-height: none; }
  .stage-frame { height: 68vw; min-height: 320px; }
  .transport { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  button { transition: none; }
}

