}

#garden {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

#garden.dragging { cursor: grabbing; }

.stage-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  padding: 8px 6px 2px;
}

.hint, .note {
  margin: 0;
  color: #5c5146;
  font-size: 0.92rem;
}

.beads {
  display: flex;
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-variant-numeric: tabular-nums;
}

.beads i {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 99px;
  margin-right: 0.3rem;
}

.fruit { background: #67a832; }
.blue { background: #2a74d6; }
.red { background: #d24b43; }

#inspect {
  position: absolute;
  left: 18px;
  bottom: 52px;
  width: min(280px, calc(100% - 36px));
  background: #fff8ec;
  border: 1px solid #e4d2b6;
  border-radius: 14px;
  padding: 10px 12px;
  box-shadow: 0 6px 0 rgba(120, 72, 32, 0.16);
}

#inspect h2 { font-size: 1rem; }

#inspect dl {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 10px;
  margin: 8px 0 0;
}

#inspect dt { color: #5c5146; }
#inspect dd { margin: 0; font-variant-numeric: tabular-nums; }

.panel {
  padding: 12px 12px 4px;
  max-height: calc(70vh + 48px);
  overflow: auto;
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 8px;
}

.presets button {
  padding: 0.35rem 0.65rem;
  font-size: 0.86rem;
}

.blurb {
  min-height: 2.6em;
  margin: 0 0 10px;
  color: #5c5146;
}

fieldset {
  border: 0;
  padding: 0;
  margin: 0 0 12px;
}

legend {
  font-weight: 600;
  margin-bottom: 6px;
}

.setup-note {
  margin: 0 0 8px;
  color: #5c5146;
  font-size: 0.86rem;
}

.field {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0 8px;
  margin-bottom: 8px;
}

.field label { font-size: 0.9rem; }

.field .value {
  font-variant-numeric: tabular-nums;
  color: #5c5146;
}

.field input[type="range"] { grid-column: 1 / -1; width: 100%; }

.field input[type="number"] {
  grid-column: 1 / -1;
  width: 100%;
  border: 1px solid #e4d2b6;
  border-radius: 8px;
  padding: 0.3rem 0.45rem;
  background: #fff;
}

.group-garden { accent-color: #2f6a45; }
.group-blue { accent-color: #2a74d6; }
.group-red { accent-color: #d24b43; }
.group-setup { accent-color: #8a5a32; }

.charts {
  margin-top: 14px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.card { padding: 12px 14px 14px; }

.card canvas {
  width: 100%;
  height: 220px;
  display: block;
  margin-top: 8px;
}

.span { grid-column: 1 / -1; }

.legend { margin: 8px 0 0; font-variant-numeric: tabular-nums; }

#summary p { margin: 0 0 6px; }

@media (max-width: 900px) {
  .layout, .charts { grid-template-columns: 1fr; }
  .panel { max-height: none; }
  .stage-frame { height: 68vw; min-height: 320px; }
  .transport { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  button { transition: none; }
}

