  line-height: 1.4;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1100px 640px at 50% 0%, #e2b57e, transparent 70%),
    #c48955;
}

button, input { font: inherit; color: inherit; }

.app {
  width: min(1180px, calc(100% - 24px));
  margin: 0 auto;
  padding: 16px 0 28px;
}

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 18px;
  margin-bottom: 12px;
}

h1 {
  margin: 0;
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  letter-spacing: -0.03em;
  line-height: 1;
}

h2 {
  margin: 0 0 4px;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
}

.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

button {
  background: #fff8ec;
  border: 1px solid #ddc7a4;
