  height: min(70vh, 720px);
  min-height: 420px;
  border-radius: 12px;
  overflow: hidden;
  background: #e7c99a;
}

#garden {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

#garden.dragging { cursor: grabbing; }

.stage-foot {
