const failures: string[] = [];

function assert(cond: boolean, message: string) {
  if (!cond) failures.push(message);
}

function run(params: Params, seconds: number) {
  const sim = createSim(params);
  const marks: Sample[] = [];
  const stride = 5;
  for (let t = 0; t < seconds; t += stride) {
