import { balanced } from "../src/presets.ts";
import { createSim, stepSim } from "../src/sim.ts";
import type { Params } from "../src/types.ts";

function peaks(values: number[]) {
  let count = 0;
  let last = -99;
  for (let i = 1; i < values.length - 1; i += 1) {
    if (values[i] >= values[i - 1] && values[i] > values[i + 1] && values[i] >= 4 && i - last >= 4) {
      count += 1;
      last = i;
    }
  }
  return count;
}

function trial(overrides: Partial<Params>, seconds = 240) {
  const params: Params = { ...balanced, ...overrides };
  const sim = createSim(params);
  const blue: number[] = [];
  const red: number[] = [];
  for (let t = 0; t < seconds; t += 5) {
    stepSim(sim, 5);
    const last = sim.history[sim.history.length - 1];
    blue.push(last.blue);
    red.push(last.red);
  }
  const late = Math.floor(blue.length * 0.55);
  const minB = Math.min(...blue.slice(late));
  const minR = Math.min(...red.slice(late));
  const score = (minB > 0 ? 20 : 0) + (minR > 0 ? 20 : 0) + peaks(blue) * 8 + peaks(red) * 8 - (Math.max(...blue) > 90 ? 15 : 0);
  return { score, minB, minR, maxB: Math.max(...blue), maxR: Math.max(...red), endB: blue.at(-1), endR: red.at(-1), pB: peaks(blue), pR: peaks(red), blue, red };
}

const results = [];
for (const redContact of [1.5, 2.1, 2.7]) {
  for (const redCopy of [11, 14, 17]) {
    for (const redPause of [1.4, 2.2]) {
      for (const reds of [3, 5]) {
        const row = trial({ redContact, redCopy, redPause, reds, seed: 42 });
        results.push({ redContact, redCopy, redPause, reds, ...row });
      }
    }
  }
}
results.sort((a, b) => b.score - a.score);
for (const row of results.slice(0, 8)) {
  console.log(
    `score=${row.score} c=${row.redContact} copy=${row.redCopy} pause=${row.redPause} reds=${row.reds} min=${row.minB}/${row.minR} max=${row.maxB}/${row.maxR} end=${row.endB}/${row.endR} peaks=${row.pB}/${row.pR}`,
  );
  console.log("  B", row.blue.join(","));
  console.log("  R", row.red.join(","));
}

