  const sway = Math.sin(tree.spin + tree.nibble * 8) * 0.04;
  const root = project(tree.x, 0, tree.z);
  const top = project(tree.x + sway, 0.72, tree.z);
  ctx.strokeStyle = "#8a5a32";
  ctx.lineWidth = Math.max(3, root.k * 0.16);
  ctx.lineCap = "round";
  ctx.beginPath();
