  const puffs = [
    { x: 0, y: 1.05, z: 0, rad: 0.78, color: "#2f7d45" },
    { x: -0.28, y: 1.28, z: 0.1, rad: 0.58, color: "#3e9a52" },
    { x: 0.32, y: 1.34, z: -0.05, rad: 0.52, color: "#67b86a" },
