  ctx.arc(x, y, Math.max(1.5, r), 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,0.75)";
  ctx.beginPath();
  ctx.arc(x - r * 0.28, y - r * 0.32, Math.max(1, r * 0.22), 0, Math.PI * 2);
  ctx.fill();
}

